styles:
/* ===== Single job posting (scoped) ===== */
.page-career .career-hero { padding-top: clamp(140px, 18vh, 220px); padding-bottom: clamp(24px, 4vw, 48px); }
.page-career .career-back {
  display: inline-flex; align-items: center; gap: 8px;
  color: var(--grey-500); font-size: 15px; margin-bottom: clamp(22px, 3vw, 36px);
  transition: color .25s var(--ease);
}
.page-career .career-back:hover { color: var(--red); }
.page-career .career-back svg { transition: transform .25s var(--ease); }
.page-career .career-back:hover svg { transform: translateX(-3px); }

.page-career .career-hero__eyebrow { margin-bottom: 16px; }
.page-career .career-hero__title {
  font-family: var(--font-display);
  font-size: clamp(40px, 6.4vw, 88px);
  line-height: 1.06; color: var(--grey-700); letter-spacing: -0.01em;
  max-width: 16ch;
}
.page-career .career-meta {
  display: flex; flex-wrap: wrap; gap: clamp(14px, 2vw, 30px);
  margin-top: clamp(24px, 3vw, 38px);
}
.page-career .career-meta__item {
  display: flex; flex-direction: column; gap: 4px;
  padding-right: clamp(14px, 2vw, 30px);
  border-right: 1px solid var(--line);
}
.page-career .career-meta__item:last-child { border-right: 0; padding-right: 0; }
.page-career .career-meta__label {
  font-size: 13px; letter-spacing: .12em; text-transform: uppercase; color: var(--grey-500);
}
.page-career .career-meta__value {
  font-family: var(--font-display); font-size: clamp(17px, 1.4vw, 21px); color: var(--grey-900);
}

.page-career .career-figure { border-radius: var(--radius-lg); overflow: hidden; background: var(--bg-alt); }
.page-career .career-figure img { width: 100%; height: auto; aspect-ratio: 16 / 8; object-fit: cover; }

/* readable single-column measure */
.page-career .career-body { max-width: 760px; margin-inline: auto; }
.page-career .career-block { margin-bottom: clamp(40px, 5vw, 66px); }
.page-career .career-block:last-child { margin-bottom: 0; }
.page-career .career-block h2 {
  font-family: var(--font-display); font-size: clamp(26px, 3vw, 40px);
  color: var(--grey-900); line-height: 1.1; margin-bottom: clamp(16px, 1.8vw, 22px);
}
.page-career .career-lede {
  font-family: var(--font-display); font-size: clamp(20px, 2vw, 28px);
  color: var(--red); line-height: 1.3; margin-bottom: 18px;
}
.page-career .career-block p { color: var(--grey-700); font-size: clamp(16px, 1.15vw, 19px); margin-bottom: 16px; }
.page-career .career-block p:last-child { margin-bottom: 0; }
.page-career .career-list { display: flex; flex-direction: column; gap: 14px; margin-top: 4px; }
.page-career .career-list li {
  position: relative; padding-left: 30px;
  color: var(--grey-700); font-size: clamp(16px, 1.1vw, 18px); line-height: 1.55;
}
.page-career .career-list li::before {
  content: ""; position: absolute; left: 0; top: .62em;
  width: 9px; height: 9px; border-radius: 50%; background: var(--red);
}

.page-career .career-apply {
  margin-top: clamp(26px, 3vw, 40px);
  padding: clamp(28px, 3.4vw, 48px);
  background: var(--bg-alt); border-radius: var(--radius-lg);
}
.page-career .career-apply h2 { margin-bottom: 14px; }
.page-career .career-apply .cta__btn { color: #fff; background: var(--red); margin-top: 26px; }
.page-career .career-apply .cta__btn .arrow { background: #fff; color: var(--red); }

@media (max-width: 560px) {
  .page-career .career-meta__item { border-right: 0; padding-right: 0; }
}
